# Coverage handling.
# MIN_COVERAGE is the threshold used either for reporting (default) or for
# an actual discard filter, depending on DISCARD_LOW_COVERAGE below.
#
# DISCARD_LOW_COVERAGE = False (default): profiles are NEVER dropped for low
# coverage. Every profile with >= MIN_LEVELS raw points is kept; grid
# positions outside its real pressure range are filled with 0 and flagged
# False in `mask`. This keeps the SAME population of profiles as the tabular
# pipeline (no depth-based sampling bias when comparing models). Downstream
# training/evaluation code MUST multiply the reconstruction loss by `mask`
# so filled positions never contribute.
#
# DISCARD_LOW_COVERAGE = True: reverts to the original behavior -- profiles
# covering less than MIN_COVERAGE of the grid are discarded outright. Left
# in place ("por si acaso") in case you want to reproduce that behavior or
# compare both settings, but it will make the CNN's profile population
# diverge from the tabular one (see compare_profile_sets.py).
MIN_COVERAGE          = 0.5
DISCARD_LOW_COVERAGE  = False

filter_juld_qc = (SPLIT_MODE == "time")
desc_tag   = "ascA" if ASCENDING_ONLY else "ascAD"
dmode_tag  = "_dmodeD" if DELAYED_MODE_ONLY else ""
cov_tag    = "_covfilt" if DISCARD_LOW_COVERAGE else "_masked"

