        print()
        print("╔" + "=" * 108 + "╗")
        print("║" + " " * 35 + "FINAL PREPROCESSING REPORT" + " " * 47 + "║")
        print("╚" + "=" * 108 + "╝")
        print()

        # ---- DATA REDUCTION ----
        print(" DATA REDUCTION SUMMARY")
        print("  " + "-" * 106)
        print(f"    Raw observations (input)           : {self.total_raw:>20,}")
        print(f"    Observations after cleaning        : {self.total_cleaned:>20,}")
        print(f"    Observations discarded             : {self.total_raw - self.total_cleaned:>20,} "
              f"({(1 - self.total_cleaned/self.total_raw)*100:>5.1f}%)")
        print(f"    Valid profiles (gridded)           : {self.n_valid_profiles:>20,}")
        print()

        # ---- SPLITS ----
        print("  TRAIN/VAL/TEST SPLIT DISTRIBUTION")
        print("  " + "-" * 106)
